<script setup lang="ts">
import { fullName, nameOr } from '@/utils/people'
import { computed, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppStatusChip from '@/Components/AppStatusChip.vue'
import AppEmptyState from '@/Components/common/AppEmptyState.vue'
import DeviceRevokeDialog from '@/Components/devices/DeviceRevokeDialog.vue'
import DeviceTable from '@/Components/devices/DeviceTable.vue'
import PageHeader from '@/Components/layout/PageHeader.vue'
import { useDeviceRevocation } from '@/composables/useDeviceRevocation'
import { getApiErrorMessage } from '@/utils/api-error'
import { useDeviceStore } from '@/stores/device.store'
import { useAdministratorStore } from '@/stores/administrator.store'
import { useUiFeedbackStore } from '@/stores/ui-feedback.store'
import type { EnterpriseUserRole } from '@/types/administrator'
import type { DeviceResponse } from '@/types/device'
const route = useRoute(); const store = useAdministratorStore(); const feedback = useUiFeedbackStore(); const user = computed(() => store.findUser(route.params.userId as string)); const team = computed(() => store.findTeam(user.value?.teamId)); const canReactivate = computed(() => store.canReactivateUsers)
const router = useRouter(); const deviceStore = useDeviceStore(); const revocation = useDeviceRevocation(); const userId = computed(() => route.params.userId as string); const devices = computed(() => deviceStore.devicesByUser[userId.value] ?? [])
const viewDevice = (device: DeviceResponse) => router.push({ name: 'admin-device-details', params: { deviceId: device.id } })
onMounted(() => { store.ensureUsers([userId.value]).catch(() => undefined); store.loadTeamOptions().catch(() => undefined); deviceStore.loadUserDevices(userId.value).catch((error) => feedback.error(getApiErrorMessage(error, 'Impossible de charger les appareils de cet utilisateur.'))) })
const roleLabels: Record<EnterpriseUserRole, string> = { administrator: 'Administrateur', supervisor: 'Superviseur', teamLeader: 'Chef d’équipe', agent: 'Agent' }
async function changeStatus() { if (!user.value) return; const wasDisabled = user.value.status === 'disabled'; if (wasDisabled && !canReactivate.value) { feedback.error("L’API ne fournit pas encore de réactivation utilisateur."); return } const action = wasDisabled ? 'Réactiver' : 'Désactiver'; const confirmed = await feedback.askConfirmation({ title: `${action} ce compte ?`, message: `Cette action concerne ${fullName(user.value)}.`, confirmText: action, color: wasDisabled ? 'success' : 'error' }); if (!confirmed) return; try { await store.toggleUserStatus(user.value.id); feedback.success(wasDisabled ? 'Compte réactivé.' : 'Compte désactivé.') } catch (error) { feedback.error(getApiErrorMessage(error, 'Action impossible.')) } }
</script>
<template><div class="mx-auto w-full max-w-[1050px]"><PageHeader><template #title>{{ nameOr(user, 'Utilisateur introuvable') }}</template><template #description>Profil, accès et affectation de l’utilisateur.</template><template #actions><v-btn variant="outlined" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-users' }">Retour</v-btn><v-btn v-if="user" color="primary" prepend-icon="mdi-pencil-outline" :to="{ name: 'admin-user-edit', params: { userId: user.id } }">Modifier</v-btn></template></PageHeader><v-alert v-if="!user" type="error" variant="tonal" title="Utilisateur introuvable" /><div v-else class="grid gap-6 lg:grid-cols-[1fr_320px]"><v-card><v-card-title class="px-6 py-5">Informations professionnelles</v-card-title><v-divider /><v-card-text class="grid gap-5 px-6 py-6 sm:grid-cols-2"><div><p class="text-xs text-[#848484]">E-mail</p><p class="mt-1 font-medium">{{ user.email }}</p></div><div><p class="text-xs text-[#848484]">Téléphone</p><p class="mt-1 font-medium">{{ user.phone }}</p></div><div><p class="text-xs text-[#848484]">Matricule</p><p class="mt-1 font-medium">{{ user.employeeNumber }}</p></div><div><p class="text-xs text-[#848484]">Équipe</p><p class="mt-1 font-medium">{{ team?.name ?? 'Aucune — ce rôle n’exige pas d’équipe' }}</p></div><div><p class="text-xs text-[#848484]">Rôle</p><p class="mt-1 font-medium">{{ roleLabels[user.role] }}</p></div></v-card-text></v-card><v-card><v-card-text class="pa-6"><div class="flex items-center justify-between"><span class="font-bold">État du compte</span><AppStatusChip :status="user.status" /></div><v-divider class="my-5" /><v-btn block variant="tonal" :color="user.status === 'disabled' ? 'success' : 'error'" :prepend-icon="user.status === 'disabled' ? 'mdi-account-check-outline' : 'mdi-account-off-outline'" @click="changeStatus">{{ user.status === 'disabled' ? 'Réactiver le compte' : 'Désactiver le compte' }}</v-btn></v-card-text></v-card></div><v-card v-if="user" class="mt-6 overflow-hidden"><v-card-title class="px-6 py-5">Appareils</v-card-title><v-divider /><DeviceTable v-if="devices.length" :devices="devices" :agent-name="deviceStore.agentName" :show-agent="false" @view="viewDevice" @revoke="revocation.open" /><AppEmptyState v-else icon="mdi-cellphone-off" title="Aucun appareil" description="L’appareil apparaîtra ici quand l’utilisateur activera l’application mobile." /></v-card><DeviceRevokeDialog :device="revocation.target.value" :agent-name="revocation.targetAgentName.value" :loading="revocation.isRevoking.value" :error-message="revocation.errorMessage.value" @submit="revocation.submit" @cancel="revocation.close" /></div></template>
